output_var_cov_kmate <- paste(
  "/global/scratch/users/milesroberts/moi_lab_projects/grenenet-phase2/results/",
  today,
  "/var_cov_point_estimates_kmate.tsv",
  sep = ""
)

# delete previous run
# check_file_exists(output_gt_kmate)
# check_file_exists(output_var_cov_kmate)

# check that directory exists
folder_path <- dirname(output_gt_kmate)
if (!dir.exists(folder_path)) {
  dir.create(folder_path, recursive = TRUE, showWarnings = FALSE)
}

# estimate curves once for each class of variants
var_classes <- unique(gen0$class)
var_class_loop_list <- list(var_classes[2], var_classes[1], var_classes[3], var_classes)
  
# loop over sites
# NOTE: suspected narrow subset — this loop runs only sites 29-31
# (3 of ~31); verbatim notebook state, confirm it is intended for the job.
for (site in unique(sites)[29:31]) {
  print(paste("Site:", site))
  hap_site <- hapfire %>% 
    dplyr::select(starts_with(paste(site, "_", sep = "")))
  
  for (exprep in 1:12) {
    print(paste("Rep:", exprep))
    hap_rep <- hap_site %>%
      dplyr::select(ends_with(paste("_", exprep, sep = ""))) %>%
      collect()
    
    for (cls in var_class_loop_list) {
      
      print(paste("Looping for variant class: ", paste(cls, collapse = "_"), "..."))
      cls_idx <- gen0 %>% 
        mutate(row_idx = row_number()) %>% 
        filter(class %in% cls) %>%
        pull(row_idx)
      
      # subset to variant class
      print(paste("Subsetting to variant class..."))
      gen0_cls <- gen0 %>%
        filter(row_number() %in% cls_idx)
      
      hap_cls <- hap_rep %>%
        filter(row_number() %in% cls_idx)
      
      # sort names to be in order of generation
      print(paste("Sorting columns..."))
      hap_cls <- hap_cls %>%
        relocate(all_of(sort(colnames(hap_cls))))
      
      if (ncol(hap_cls) < 2) {
        print("Need at least two increments. Skipping to next replicate...")
        next
      }
      
      print(paste("Grabbing sample sizes..."))
      rep_n <- grab_sample_sizes(flower_counts, pool, colnames(hap_cls), 10000, total_flowers)
      
      hap_cls <- cbind(gen0_cls$X0_0_0, hap_cls)
      colnames(hap_cls)[1] = paste(site, "_0_", exprep, sep = "")
      
      covmat <- covmat_from_pmat(
        hap_cls,
        rep_n$total_flowers*2,
        correct_for_n = T,
        input_asin_trans = F,
        standard_by_het = F
      )
      
      # save raw var-cov matrix
      covlong <- covmat %>%
        as.data.frame() %>%
        rownames_to_column(var = "A") %>%
        pivot_longer(cols = -A, names_to = "B", values_to = "cov")
      
      covlong$site <- site
      covlong$rep <- exprep
      covlong$class = paste(cls, collapse = "_")
      append_table(covlong, output_var_cov_kmate)
      
      # save gt statistic (per-interval standardized + B&C time-zero
      # standardized denominators: gt/gt_abs and gt_bnc/gt_bnc_abs)
      gt_result <- gt_from_covmat(covmat)
      gt_result$site = site
      gt_result$rep = exprep
      gt_result$class = paste(cls, collapse = "_")
      append_table(gt_result, output_gt_kmate)
      
      rm(covlong, covmat, gt_result, hap_cls, gen0_cls, rep_n); gc()
    }
    rm(hap_rep); gc()
  }
}

gt_class <- fread(output_gt_kmate) %>%
  distinct(site, rep, gen, class, .keep_all = T)

gt_class$gt_abs[is.na(gt_class$gt_abs) & (gt_class$gen == 1)] <- 0

gt_class$class <- gsub("smallindel_sv_snp", "all", gt_class$class)
gt_class$class <- gsub("smallindel", "indel", gt_class$class)

ggplot(gt_class, aes(x = factor(gen), y = gt_abs, group = rep, color = class)) +
  geom_point() +
  geom_line() +
  facet_wrap(~site+class) +
  scale_color_scico_d(palette = "batlow") +
  labs(x = "Generation", y = "Gabs(t)") +
  scale_y_continuous(n.breaks = 3) 

ggsave(paste0("../results/by-date/", today, "/gt_abs_kmate.pdf"), width = 11, height = 12)

# check where negative covariance is coming from
kmate_var_cov <- fread(output_var_cov_kmate) %>%
  filter(class == "sv")

kmate_var_cov <- kmate_var_cov %>% 
  mutate(i = as.numeric(gsub("_", "", str_extract(A, "_[0-9]_"))),
         j = as.numeric(gsub("_", "", str_extract(B, "_[0-9]_"))),
         dt = abs(i - j))

dt_by_cov_summary <- kmate_var_cov %>% 
  group_by(dt) %>%
  filter(!is.na(cov)) %>%
  summarize(num_neg_cov = sum(cov < 0),
            n = n(),
            prop_neg_cov = num_neg_cov/n)

ggplot(dt_by_cov_summary %>% filter(dt > 0), aes(x = dt, y = prop_neg_cov)) +
  geom_col(color = "black", fill = "black") +
  geom_text(aes(label = paste0(signif(prop_neg_cov, 3), ", n = ", n)), vjust = -0.5) +
  labs(x = "\u0394t = |i - j|", y = "Proportion of Cov(\u0394pi, \u0394pj) < 0")
  
ggsave(paste0("../results/by-date/", today, "/neg_cov_by_dt.pdf"), device = cairo_pdf, height = 5, width = 6)

## facet by site
